    inquiry_no, work_id, buyer_id, seller_id, license_type, intended_use,
    budget, message, status, expire_at, create_by, create_time, remark
) values (
    #{inquiryNo}, #{workId}, #{buyerId}, #{sellerId}, #{licenseType}, #{intendedUse},
    #{budget}, #{message}, #{status}, #{expireAt}, #{createBy}, #{createTime}, #{remark}
